static z_t1728_t* z_t1728_create(uint64_t _capacity);
static z_t1728_t* z_t1728_create(uint64_t _capacity) {
    z_t1728_t* _this = (z_t1728_t*)z_xmalloc(sizeof(z_t1728_t));
    *_this = (z_t1728_t){0};
    if (_capacity < 8) _capacity = 0;
    /* probing masks with (capacity - 1): round any caller capacity up to
       a power of two */
    if (_capacity & (_capacity - 1)) {
        uint64_t _p2 = 8;
        while (_p2 < _capacity) _p2 <<= 1;
        _capacity = _p2;
    }
    _this->capacity = _capacity;
    _this->entries_cap = _capacity;
    if (_capacity > 0) {
        _this->indices = (int64_t*)z_xmalloc(_capacity * sizeof(int64_t));
        for (uint64_t i = 0; i < _capacity; i++) {
            _this->indices[i] = Z_T1728_INDEX_EMPTY;
        }
        _this->entries = (z_t1728_entry_t*)z_xcalloc(_capacity, sizeof(z_t1728_entry_t));
    }
    return _this;
}

static void z_t1728_grow(z_t1728_t* _this);
static void z_t1728_grow(z_t1728_t* _this) {
    uint64_t old_cap = _this->capacity;
    uint64_t new_cap = old_cap == 0 ? 8 : old_cap * 2;
    z_t1728_entry_t* old_entries = _this->entries;
    uint64_t old_entries_len = _this->entries_len;
    int64_t* new_indices = (int64_t*)z_xmalloc(new_cap * sizeof(int64_t));
    for (uint64_t i = 0; i < new_cap; i++) {
        new_indices[i] = Z_T1728_INDEX_EMPTY;
    }
    z_t1728_entry_t* new_entries = (z_t1728_entry_t*)z_xcalloc(new_cap, sizeof(z_t1728_entry_t));
    uint64_t new_entries_len = 0;
    for (uint64_t i = 0; i < old_entries_len; i++) {
        if (!old_entries[i].alive) continue;
        new_entries[new_entries_len] = old_entries[i];
        uint64_t probe = old_entries[i].hash & (new_cap - 1);
        while (new_indices[probe] != Z_T1728_INDEX_EMPTY) {
            probe = (probe + 1) & (new_cap - 1);
        }
        new_indices[probe] = (int64_t)new_entries_len;
        new_entries_len++;
    }
    free(_this->indices);
    free(old_entries);
    _this->indices = new_indices;
    _this->entries = new_entries;
    _this->capacity = new_cap;
    _this->entries_cap = new_cap;
    _this->entries_len = new_entries_len;
}

static int64_t z_t1728_find(const z_t1728_t* _this, uint64_t _key, uint64_t _hash, int64_t* _slot_out);
static int64_t z_t1728_find(const z_t1728_t* _this, uint64_t _key, uint64_t _hash, int64_t* _slot_out) {
    if (_this->capacity == 0) return -1;
    uint64_t probe = _hash & (_this->capacity - 1);
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T1728_INDEX_EMPTY) {
            if (_slot_out) *_slot_out = (int64_t)probe;
            return -1;
        }
        if (slot != Z_T1728_INDEX_DELETED) {
            if (_this->entries[slot].hash == _hash && z_t1728_keys_equal(_this->entries[slot].key, _key)) {
                if (_slot_out) *_slot_out = (int64_t)probe;
                return slot;
            }
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    return -1;
}

static void z_t1728_set(z_t1728_t* _this, uint64_t _key, uint64_t _val);
static void z_t1728_set(z_t1728_t* _this, uint64_t _key, uint64_t _val) {
    uint64_t h = z_t1728_hash_key(_key);
    int64_t existing = z_t1728_find(_this, _key, h, NULL);
    if (existing >= 0) {
        _this->entries[existing].value = _val;
        return;
    }
    if (_this->capacity == 0 || (_this->entries_len + 1) * 3 >= _this->capacity * 2) {
        z_t1728_grow(_this);
    }
    uint64_t probe = h & (_this->capacity - 1);
    int64_t first_deleted = -1;
    for (uint64_t i = 0; i < _this->capacity; i++) {
        int64_t slot = _this->indices[probe];
        if (slot == Z_T1728_INDEX_EMPTY) {
            if (first_deleted >= 0) probe = (uint64_t)first_deleted;
            break;
        }
        if (slot == Z_T1728_INDEX_DELETED && first_deleted < 0) {
            first_deleted = (int64_t)probe;
        }
        probe = (probe + 1) & (_this->capacity - 1);
    }
    if (_this->entries_len >= _this->entries_cap) {
        uint64_t new_ec = _this->entries_cap == 0 ? 8 : _this->entries_cap * 2;
        _this->entries = (z_t1728_entry_t*)z_xrealloc(_this->entries, new_ec * sizeof(z_t1728_entry_t));
        for (uint64_t i = _this->entries_cap; i < new_ec; i++) {
            _this->entries[i] = (z_t1728_entry_t){0};
        }
        _this->entries_cap = new_ec;
    }
    int64_t new_idx = (int64_t)_this->entries_len;
    _this->entries[new_idx].alive = 1;
    _this->entries[new_idx].hash = h;
    _this->entries[new_idx].key = _key;
    _this->entries[new_idx].value = _val;
    _this->entries_len++;
    _this->indices[probe] = new_idx;
    _this->length++;
}

static z_t1730_t z_t1728_get(z_t1728_t* _this, uint64_t _key);
static z_t1730_t z_t1728_get(z_t1728_t* _this, uint64_t _key) {
    uint64_t h = z_t1728_hash_key(_key);
    int64_t idx = z_t1728_find(_this, _key, h, NULL);
    z_t1730_t _r;
    if (idx >= 0) {
        _r.tag = Z_OPTIONVAL_DECLID_TAG_SOME;
        _r.data.some = _this->entries[idx].value;
    } else {
        _r.tag = Z_OPTIONVAL_DECLID_TAG_NONE;
    }
    return _r;
}

static z_t1730_t z_t1728_remove(z_t1728_t* _this, uint64_t _key);
static z_t1730_t z_t1728_remove(z_t1728_t* _this, uint64_t _key) {
    uint64_t h = z_t1728_hash_key(_key);
    int64_t slot = -1;
    int64_t idx = z_t1728_find(_this, _key, h, &slot);
    z_t1730_t _r;
    if (idx < 0) {
        _r.tag = Z_OPTIONVAL_DECLID_TAG_NONE;
        return _r;
    }
    _r.tag = Z_OPTIONVAL_DECLID_TAG_SOME;
    _r.data.some = _this->entries[idx].value;
    _this->entries[idx].alive = 0;
    _this->indices[slot] = Z_T1728_INDEX_DELETED;
    _this->length--;
    return _r;
}

static int z_t1728_has(const z_t1728_t* _this, uint64_t _key);
static int z_t1728_has(const z_t1728_t* _this, uint64_t _key) {
    uint64_t h = z_t1728_hash_key(_key);
    return z_t1728_find(_this, _key, h, NULL) >= 0;
}

typedef struct {
    z_t1728_t* m;
    uint64_t idx;
} z_t1738_t;

static z_t1037_t z_t1738_call(z_t1738_t* _it);
static z_t1037_t z_t1738_call(z_t1738_t* _it) {
    z_t1037_t _out = {0};
    while (_it->idx < _it->m->entries_len) {
        if (_it->m->entries[_it->idx].alive) {
            _out.tag = Z_OPTIONVIEW_U64_TAG_SOME;
            _out.data = &_it->m->entries[_it->idx].key;
            _it->idx++;
            return _out;
        }
        _it->idx++;
    }
    _out.tag = Z_OPTIONVIEW_U64_TAG_NONE;
    return _out;
}

static z_t1738_t z_t1728_iterate(const z_t1728_t* _this);
static z_t1738_t z_t1728_iterate(const z_t1728_t* _this) {
    z_t1738_t _it = {0};
    /* The cursor keeps a plain T* and OptionView's payload is a single void*, shared
   with the readers that hand out a mutable interior pointer on purpose
   (List.get's write-back), so const cannot propagate that far without breaking
   them. This ONE cast is where it stops. What the const receiver buys is still
   real and is what view-guard checks: `iterate` itself provably does not write
   through the container. That the ELEMENTS are readonly is a typecheck-level
   guarantee -- the loop element inherits the strength of the lock its holder
   has on the container -- not a C one. */
    _it.m = (z_t1728_t*)_this;
    _it.idx = 0;
    return _it;
}

